def _tag_end(html: str, start: int) -> int | None:
    """Return the position after a tag's closing ``>``, respecting quotes."""
    quote: str | None = None

    for index in range(start, len(html)):
        character = html[index]
        if quote is not None:
            if character == quote:
                quote = None
        elif character in "'\"":
            quote = character
        elif character == ">":
            return index + 1

    return None


def _script_end(html: str, start: int) -> int | None:
    """Find the end of the next case-insensitive script end tag."""
    search_from = start

    while True:
        candidate = html.find("<", search_from)
        if candidate < 0:
            return None

        name_start = candidate + 2
        name_end = name_start + len("script")
        if (
            html.startswith("/", candidate + 1)
            and html[name_start:name_end].lower() == "script"
            and name_end < len(html)
            and html[name_end] in _TAG_NAME_END
        ):
            end = _tag_end(html, name_end)
            if end is not None:
                return end

        search_from = candidate + 1


