        closing_end = _script_end(html, opening_end)
        if closing_end is None:
            unchanged_from = len(html)
            search_from = len(html)
            break

        unchanged_from = closing_end
        search_from = closing_end

    output.append(html[unchanged_from:])
    return "".join(output)

